mkdir -p /etc/keepalived; cat > /etc/keepalived/keepalived.conf <<'EOF'
vrrp_instance VI_1 {
    state MASTER
    interface br-lan
    virtual_router_id 51
    priority 150
    advert_int 1
    virtual_ipaddress {
        10.100.53.200/24 dev br-lan
    }
}
EOF
cat /etc/keepalived/keepalived.conf

